-- 0358 PROD CHECK (before), read-only, ONE statement: npx --yes supabase@2.120.0 db query --linked -f scripts/ops/harness/yard-sources/before-hunks.sql
-- Wanted: 3 rows; every old_times 1 and new_times 0; volatility s, definer true, search_path public, pg_temp, ACL postgres and authenticated only; head = the migration before 0358 in the deploy order.
-- Generated by scripts/ops/harness/yard-sources/gen-checks.mjs from the migration's own hunks. Only the catalog is read.
begin transaction read only;
with h(ord, old, new) as (values
  (1, $h$  sold as materialized (
    select distinct on (g.id) g.id as good_id, d.code, d.name, d.miles
      from public.hull_recipe_goods hg
      join public.goods g on g.id = hg.good_id
      cross join dist d
      join lateral public.port_offered_goods(d.id) o on o.good_id = g.id
     where hg.class_code = p_class
       and not public.culture_refuses(d.culture, g.culture_mask)
     order by g.id, d.miles nulls last, d.name),
$h$, $h$  -- 0358: THE WHOLE LIST. `need` is every good the hull takes: her own (hull_recipe_goods) and the goods her parts are made of (hull_recipe_items x item_recipes), one row a good.
  -- `near` is 0349's nearest seller, for each of them, keeping the seller's port id. `sold` adds what that seller asks for one now: world.price, the one price authority, once a good
  -- (null where the seller has no market row). Added keys only: goods[] gain qty, bulk, ask; items[] gain inputs [{code, good, qty, bulk, port, name, miles, ask}].
  need as materialized (
    select hg.good_id from public.hull_recipe_goods hg where hg.class_code = p_class
    union
    select ir.good_id from public.hull_recipe_items hi join public.item_recipes ir on ir.item_code = hi.item_code where hi.class_code = p_class),
  near as materialized (
    select distinct on (g.id) g.id as good_id, d.id as port_id, d.code, d.name, d.miles
      from need hg
      join public.goods g on g.id = hg.good_id
      cross join dist d
      join lateral public.port_offered_goods(d.id) o on o.good_id = g.id
     where not public.culture_refuses(d.culture, g.culture_mask)
     order by g.id, d.miles nulls last, d.name),
  sold as materialized (
    select n.good_id, n.port_id, n.code, n.name, n.miles,
           (select pr.ask from public.port_goods pg cross join lateral world.price(pg.port_id, pg.good_id) pr
             where pg.port_id = n.port_id and pg.good_id = n.good_id) as ask
      from near n),
$h$),
  (2, $h$      select jsonb_agg(jsonb_build_object('code', g.code, 'port', s.code, 'name', s.name, 'miles', round(s.miles)) order by g.code)
$h$, $h$      select jsonb_agg(jsonb_build_object('code', g.code, 'port', s.code, 'name', s.name, 'miles', round(s.miles),
                                          'qty', hg.qty, 'bulk', g.bulk, 'ask', s.ask) order by g.code)
$h$),
  (3, $h$      select jsonb_agg(jsonb_build_object('code', k.code, 'port', m.code, 'name', m.name, 'miles', round(m.miles)) order by k.code)
$h$, $h$      select jsonb_agg(jsonb_build_object('code', k.code, 'port', m.code, 'name', m.name, 'miles', round(m.miles),
                                          'inputs', coalesce((
                                            select jsonb_agg(jsonb_build_object('code', g.code, 'good', g.name, 'qty', ir.qty * hi.qty, 'bulk', g.bulk,
                                                                                'port', s.code, 'name', s.name, 'miles', round(s.miles), 'ask', s.ask) order by g.code)
                                              from public.item_recipes ir join public.goods g on g.id = ir.good_id
                                              left join sold s on s.good_id = g.id
                                             where ir.item_code = k.code), '[]'::jsonb)) order by k.code)
$h$)),
live as (select replace(pg_get_functiondef('world.yard_sources(uuid,text)'::regprocedure), E'\r', '') as def)
select h.ord,
       (length(live.def) - length(replace(live.def, h.old, ''))) / length(h.old) as old_times,
       (length(live.def) - length(replace(live.def, h.new, ''))) / length(h.new) as new_times,
       (select p.provolatile::text || ':' || p.prosecdef::text || ':' || coalesce(p.proconfig::text, '') || ':' || coalesce(p.proacl::text, '')
          from pg_proc p where p.oid = 'world.yard_sources(uuid,text)'::regprocedure) as volatility_definer_config_acl,
       md5(live.def) as body_md5,
       (select max(version) from supabase_migrations.schema_migrations) as head
  from h cross join live
 order by h.ord;
commit;
